// src/helpers/showToast.ts
function showToast(message, type, duration = 3e3) {
  let container = document.querySelector(".toast-container");
  if (!container) {
    container = document.createElement("div");
    container.className = "toast-container";
    document.body.appendChild(container);
  }
  const toast = document.createElement("div");
  toast.className = `toast toast-${type}`;
  toast.textContent = message;
  container.appendChild(toast);
  setTimeout(() => toast.classList.add("visible"), 100);
  setTimeout(() => {
    toast.classList.remove("visible");
    setTimeout(() => toast.remove(), 300);
  }, duration);
}

// src/forkop/methods/shell/callBaseMethod.ts
async function callBaseMethod(method, args = [], command = "/usr/bin/forkop", options = {}) {
  try {
    const response = await executeShellCommand({
      command,
      args: [method, ...args],
      timeout: options.timeout ?? 15e3
    });
    const exitCode = response.code ?? 0;
    if (exitCode !== 0 && !(options.allowNonZeroWithStdout && response.stdout)) {
      return {
        success: false,
        error: response.stderr || response.stdout || ""
      };
    }
    if (response.stdout) {
      try {
        return {
          success: true,
          data: JSON.parse(response.stdout)
        };
      } catch (_e) {
        return {
          success: true,
          data: response.stdout
        };
      }
    }
    return {
      success: false,
      error: response.stderr || ""
    };
  } catch (error) {
    return {
      success: false,
      error: error instanceof Error ? error.message : ""
    };
  }
}

