// src/forkop/tabs/dashboard/serviceActionFlow.ts
async function runOverviewServiceAction(steps) {
  steps.setBusy(true);
  try {
    await steps.run();
  } catch (error) {
    steps.onError(error);
  } finally {
    try {
      await steps.refreshRuntime();
      await steps.refreshHealth();
    } finally {
      steps.setBusy(false);
    }
  }
}

